function registerCanvasTool(server, config2, name) {
  const schema = toolInputSchemas[name];
  server.registerTool(name, { description: toolDescriptions[name], inputSchema: schema.shape }, async (input) => {
    const result = await postCanvasAgentTool(config2, name, schema.parse(input));
    return { content: [{ type: "text", text: JSON.stringify(result, null, 2) }] };
  });
}
async function postCanvasAgentTool(config2, name, input) {
  const res = await fetch(`${config2.url}/api/tools`, { method: "POST", headers: { "content-type": "application/json", "x-canvas-agent-token": config2.token }, body: JSON.stringify({ name, input }) });
  const body = await res.json();
  if (!body.ok) throw new Error(body.error || "tool call failed");
  return body.result;
}

